<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $vehicle->plaka }} araç defteri</title><style>:root{--blue:#176b87;--green:#0f9d78;--ink:#17324d}*{box-sizing:border-box}body{margin:0;background:#f4f8fa;color:var(--ink);font-family:system-ui}.wrap{width:min(1040px,calc(100% - 2rem));margin:2rem auto}.hero{background:linear-gradient(135deg,var(--blue),var(--green));color:#fff;padding:2rem;border-radius:24px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:1rem;margin-top:1rem}.card{background:#fff;border-radius:18px;padding:1.25rem;box-shadow:0 7px 26px #16324d12}.muted{color:#64748b}.row{padding:.7rem 0;border-bottom:1px solid #e5edf2}.amount{font-weight:800;color:var(--blue)}img{width:100%;border-radius:12px}button{background:#fff2;border:1px solid #fff8;color:#fff;border-radius:9px;padding:.6rem 1rem}</style></head><body><main class="wrap"><section class="hero"><form method="post" action="{{ route('vehicle.logout') }}" style="float:right">@csrf<button>Çıkış</button></form><div class="muted" style="color:#d9f5ed">ARAÇ DEFTERİ</div><h1>{{ $vehicle->plaka }}</h1><div>{{ $vehicle->marka }} {{ $vehicle->model }} @if($vehicle->model_yili) · {{ $vehicle->model_yili }}@endif · {{ number_format($vehicle->guncel_km,0,',','.') }} km</div></section><div class="grid"><section class="card"><h2>Bakiye</h2>@forelse($balances as $b)<div class="row">{{ $b->debtor?->ad }} → {{ $b->payer?->ad }} <span class="amount">{{ number_format($b->toplam,2,',','.') }} ₺</span></div>@empty<p class="muted">Açık alacak yok.</p>@endforelse</section><section class="card"><h2>Künye</h2><p>Sahip: {{ $vehicle->owner?->ad??'—' }}</p><p>Renk: {{ $vehicle->renk??'—' }} · Yakıt: {{ $vehicle->yakit_cinsi??'—' }}</p><p>Donanım: {{ implode(', ',$vehicle->donanimlar??[])?:'—' }}</p></section></div><section class="card" style="margin-top:1rem"><h2>Masraf defteri</h2>@forelse($vehicle->expenses as $e)<div class="row"><strong>{{ $e->tarih->format('d.m.Y') }} · {{ $e->aciklama }}</strong><div class="muted">{{ $e->kategori }} · Ödeyen {{ $e->payer?->ad }} @if($e->debtor) · Borçlu {{ $e->debtor->ad }} @endif · {{ $e->mahsup_durumu }}</div><span class="amount">{{ number_format($e->tutar,2,',','.') }} ₺</span></div>@empty<p>Kayıt yok.</p>@endforelse</section><div class="grid"><section class="card"><h2>Sorun ve görevler</h2>@forelse($vehicle->issues as $i)<div class="row"><strong>{{ $i->baslik }}</strong><div class="muted">{{ $i->kategori }} · {{ $i->durum }}</div></div>@empty<p>Kayıt yok.</p>@endforelse</section><section class="card"><h2>Medya</h2><div class="grid">@foreach($vehicle->media as $m)<div><a href="{{ route('vehicle.owner.media',$m) }}">@if(str_starts_with($m->mime_type,'image/'))<img src="{{ route('vehicle.owner.media',$m) }}" alt="{{ $m->caption }}">@else{{ $m->caption?:$m->role }}@endif</a></div>@endforeach</div></section></div></main></body></html>
